window.roroSubmitButton=function(r=null,o=null){if(!o||!r)return;const t=$("#"+o),n=$("#"+r);if("submit"!==n.prop("type"))return;roroShowOverlay(!0);n.data("ajax")?(()=>{if(!t[0].reportValidity())return void roroShowOverlay(!1);const r=new FormData(t[0]);$.ajax({url:t.attr("action"),type:(t.attr("method")||"POST").toUpperCase(),data:r,contentType:!1,processData:!1}).done(r=>t.trigger("roro:ajax:success",[r])).fail((r,o,e)=>{t.trigger("roro:ajax:error",[r,o,e]),n.data("ajax-errors")&&r.responseJSON?.errors&&populateFormErrors(t,r.responseJSON.errors)}).always(()=>roroShowOverlay(!1))})():t[0].reportValidity()?t.submit():roroShowOverlay(!1)},window.roroRegisterButtonOnClick=function(r){const o=$("#"+r);o.length&&o.on("click",function(r){r.preventDefault(),roroSubmitButton(o.attr("id"),o.data("form-id"))})},window.roroShowOverlay=function(r=!0){const o=$("#roro-form-overlay");o.length&&(r?o.fadeIn(150):o.fadeOut(150))},window.populateFormErrors=function(r,o){clearFormErrors(r);for(let[t,n]of Object.entries(o)){t=normalizeInputName(t);const o=r.find(`[name="${t}"]`);o.length&&roroShowError(o.attr("id"),n.join(", "),!0)}},window.clearFormErrors=function(r){r.find(".roro-input").each(function(){roroShowError($(this).attr("id"),"",!1)})},$(document).ready(function(){$(".roro-btn-submit").each(function(){roroRegisterButtonOnClick($(this).attr("id"))}),$(".roro-border-error").each(function(){manageBorderError($(this))})});